export function widen(pose: CameraPose, factor: number): CameraPose {
  const [px, py, pz] = pose.position, [tx, ty, tz] = pose.target;
  return { ...pose, position: [tx + (px - tx) * factor, ty + (py - ty) * factor, tz + (pz - tz) * factor] };
}

