}

export interface CardOption { id: string; name: string; note?: string; meta?: string; swatch?: readonly string[] }

/** Native radio group drawn as cards: arrow keys move, Space selects, the name is always text. */
export function OptionCards({ name, legend, value, options, onChange, columns = 2, disabled }: {
  name: string; legend: string; value: string; options: readonly CardOption[]; onChange: (id: string) => void; columns?: 1 | 2 | 3; disabled?: boolean;
}) {
  return (
    <fieldset className="m-0 min-w-0 border-0 p-0" disabled={disabled}>
      <legend className="mk-sr-only">{legend}</legend>
      <div className={`grid gap-2 ${columns === 3 ? 'grid-cols-1 @md:grid-cols-3' : columns === 2 ? 'grid-cols-1 @xs:grid-cols-2' : 'grid-cols-1'}`}>
        {options.map((o) => (
          <label key={o.id} className={styles.card}>
            <input type="radio" className="mk-sr-only" name={name} value={o.id} checked={value === o.id} onChange={() => onChange(o.id)} />
            {o.swatch ? (
              <span aria-hidden="true" className={styles.swatch}>
                {o.swatch.map((c, i) => <span key={i} style={{ background: c }} />)}
              </span>
            ) : null}
            <span className="grid min-w-0 flex-1 gap-0.5">
              <span className="flex items-baseline justify-between gap-2">
                <span className={`${styles.cardName} text-[14px] leading-tight`}>{o.name}</span>
                {o.meta ? <span className="whitespace-nowrap font-mono text-[11.5px] text-muted">{o.meta}</span> : null}
              </span>
              {o.note ? <span className="text-[12.5px] leading-snug text-muted">{o.note}</span> : null}
            </span>
          </label>
        ))}
      </div>
    </fieldset>
  );
}

/** Compact segmented radio group (camera views). */
export function Segmented({ name, legend, value, options, onChange, disabled }: {
  name: string; legend: string; value: string | null; options: readonly { id: string; label: string }[]; onChange: (id: string) => void; disabled?: boolean;
}) {
  return (
    <fieldset className="m-0 min-w-0 border-0 p-0" disabled={disabled}>
      <legend className="mk-sr-only">{legend}</legend>
      <div className={styles.segmented}>
        {options.map((o) => (
          <label key={o.id} className={styles.segment}>
            <input type="radio" className="mk-sr-only" name={name} value={o.id} checked={value === o.id} onChange={() => onChange(o.id)} />
            <span>{o.label}</span>
          </label>
        ))}
      </div>
    </fieldset>
  );
}

/* Pulse configurator — warm studio paper, ink hairlines, one accent. */
.stage {
  position: relative;
  overflow: hidden;
  width: 100%;
  aspect-ratio: 1 / 1;
  max-height: 74svh;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-m, 10px);
  background:
    radial-gradient(90% 70% at 50% 42%, color-mix(in srgb, var(--mk-surface, #fbf9f4) 94%, #fff) 0%, var(--mk-surface-2, #e9e5da) 68%, color-mix(in srgb, var(--mk-surface-2, #e9e5da) 88%, #000) 100%);
}
:global([data-theme='dark']) .stage {
  background: radial-gradient(90% 70% at 50% 40%, #34332d 0%, #22221e 60%, #141412 100%);
}
@container (width >= 48rem) {
  .stage { aspect-ratio: 5 / 4; }
}
.stage canvas:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: -4px; }

/* Option cards (radio) */
.card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 10px;
  min-height: 52px;
  padding: 9px 12px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-s, 4px);
  background: var(--mk-surface, #fbf9f4);
  cursor: pointer;
  transition: border-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), box-shadow var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.card:hover { border-color: var(--mk-line-strong, #11110f); }
.card:has(input:checked) { border-color: var(--mk-line-strong, #11110f); box-shadow: inset 0 0 0 1px var(--mk-line-strong, #11110f); }
.cardName { font-weight: 500; }
.card:has(input:checked) .cardName { font-weight: 700; }
.card:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
fieldset:disabled .card { cursor: not-allowed; }

.swatch {
  display: flex;
  flex: none;
  width: 28px;
  height: 28px;
  overflow: hidden;
  border-radius: 50%;
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.25);
  transform: rotate(-35deg);
}
.swatch > span { flex: 1; }

/* Segmented control */
.segmented {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
}
.segment {
  display: inline-flex;
  align-items: center;
  min-height: 36px;
  padding: 0 12px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: 999px;
  font-size: 13px;
  cursor: pointer;
  background: var(--mk-surface, #fbf9f4);
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease), color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.segment:hover { border-color: var(--mk-line-strong, #11110f); }
.segment:has(input:checked) { background: var(--mk-ink, #11110f); color: var(--mk-bg, #f3f0e8); border-color: var(--mk-ink, #11110f); }
.segment:has(input:focus-visible) { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
fieldset:disabled .segment { cursor: not-allowed; color: var(--mk-ink-muted, #5c5a52); }

.iconButton {
  display: inline-grid;
  place-items: center;
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: 999px;
  background: var(--mk-surface, #fbf9f4);
  color: var(--mk-ink, #11110f);
  font: 500 13px/1 var(--mk-font-text, system-ui, sans-serif);
}
.iconButton:hover:not(:disabled) { border-color: var(--mk-line-strong, #11110f); }
.iconButton:disabled { color: var(--mk-ink-muted, #5c5a52); cursor: not-allowed; }

.range { width: 100%; accent-color: var(--mk-ink, #11110f); min-height: 24px; }

.chip {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 5px 8px;
  border-radius: 3px;
  background: var(--mk-surface, #fbf9f4);
  border: 1px solid var(--mk-line, #11110f24);
  font: 11px/1.2 var(--mk-font-mono, ui-monospace, monospace);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--mk-ink, #11110f);
}
.progress { display: block; width: 100%; height: 3px; accent-color: var(--mk-ink, #11110f); }

.partButton {
  display: flex;
  width: 100%;
  min-height: 36px;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  padding: 6px 0;
  border: 0;
  border-bottom: 1px solid var(--mk-line, #11110f24);
  background: none;
  color: inherit;
  font: inherit;
  font-size: 13.5px;
  text-align: left;
}
.partButton[aria-pressed='true'] { font-weight: 600; }
.partButton[aria-pressed='true']::before { content: '●'; color: var(--mk-accent, #8a5a00); margin-right: -4px; font-size: 9px; }

.total {
  font-family: var(--mk-font-display, system-ui, sans-serif);
  font-weight: 700;
  font-size: clamp(2rem, 7cqi, 2.6rem);
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
